        ConfigPair : name == "kms_key_name"
      ]
    ]
  ]
)

ConfigBlock : blocktype == "resource" and labels[0] matches "google_bigquery_dataset" and pairs contains [
  ConfigPair : name == "dataset_id"
]* and not (
  pairs contains [
    ConfigPair : name == "default_encryption_configuration" and value is [
      ConfigMap : pairs contains [
        ConfigPair : name == "kms_key_name"
      ]
    ]
  ]
)

ConfigBlock : blocktype == "resource" and labels[0] matches "google_compute_instance|google_compute_instance_from_template" and not contains [
  ConfigPair : name == "confidential_instance_config" and value is [
    ConfigMap : pairs contains [
      ConfigPair : name == "enable_confidential_compute" and value is [
        ConfigConcrete : value matches "(?i)true"
      ]
    ]
  ]
]*

ConfigPair : name == "cluster" and value is [
  ConfigMap : not pairs contains [
    ConfigPair : name == "kms_key_name"
  ]
]* and in [
  ConfigBlock : blocktype == "resource" and labels[0] is "google_bigtable_instance"
]*

ConfigBlock: blocktype == "resource" and  
         labels[0] == "azurerm_kubernetes_cluster_node_pool" 
         and 
             ( not attributes contains [ 
                         ConfigPair : name == "enable_host_encryption" 
                     ]
             or  
             attributes contains [ 
                 ConfigPair : name == "enable_host_encryption" and value is false
             ]* 
         )
         /* avoid duplicate findings with rule 4916B8A9-3290-4550-94DA-0DC4C91A4B21 and only identify lone blocks for azurerm_kubernetes_cluster_node_pool with no encryption */
         and  in 
         [ConfigMap: 
                 not pairs contains [ConfigPair: value is 
                         [ConfigBlock: labels[0] == "azurerm_kubernetes_cluster"]
                     ]
         ]

/* disk encryption set not defined for regular or confidential setup */
ConfigBlock: blocktype == "resource" and  
         labels[0] == "azurerm_shared_image_version" 
         and 
             /* ensure a disk encryption set is defined */
             not attributes contains [
                 ConfigBlock: blocktype == "target_region"
             ]
             or attributes contains [
                 ConfigBlock: blocktype == "target_region" and (
                     not attributes contains [ 
                         ConfigPair : name == "disk_encryption_set_id" 
                     ]
                     or  
                     attributes contains [ 
                         ConfigPair : name == "disk_encryption_set_id" and (
                             value is empty
                         or value is null
                         or value is ""
                     )
                     ]*
                 )
             ]*

/* PostgreSQL server with no infrastructure encryption */
 ConfigBlock : 
    labels[0] == "azurerm_postgresql_server" and 
    ( 
        not attributes contains [ 
            ConfigPair : name == "infrastructure_encryption_enabled"
        ]* 
        or
        attributes contains [ 
            ConfigPair : name == "infrastructure_encryption_enabled" and value == false
        ]*
    )

/* MySQL server with no infrastructure encryption */
 ConfigBlock : 
    labels[0] == "azurerm_mysql_server" and 
    ( 
        not attributes contains [ 
            ConfigPair : name == "infrastructure_encryption_enabled"
        ]* 
        or
        attributes contains [ 
            ConfigPair : name == "infrastructure_encryption_enabled" and value == false
        ]*
    )

/* blank keys for DEK */
ConfigPair: name == "secret_url" and value == "" and in [
ConfigBlock: blocktype == "disk_encryption_key" and in 
    [ConfigBlock: blocktype == "encryption_settings" and in [
        ConfigBlock: labels[0] == "azurerm_snapshot"
        ]*
    ]*
]*

/* blank keys for KEK */
ConfigPair: name == "key_url" and value == "" and in [
ConfigBlock: blocktype == "key_encryption_key" and in 
    [ConfigBlock: blocktype == "encryption_settings" and in [
        ConfigBlock: labels[0] == "azurerm_snapshot"
        ]*
    ]*
]*

/* storage account with explicitly disabled infrastructure encryption */
ConfigBlock : labels[0] == "azurerm_storage_account" and  attributes contains [ 
        ConfigPair : name == "infrastructure_encryption_enabled" and 
            value == false
    ]*

ConfigBlock: blocktype  == "resource" and  
    labels[0] == "azurerm_mssql_virtual_machine"  and
      attributes contains
         [ConfigBlock: blocktype == "auto_backup" and
           ( 
             (attributes contains
                 [ConfigPair:    name == "encryption_enabled" 
                                 and value is [ConfigConcrete: value != true]
                 ]*
             )
         or
             (not attributes contains
                 [ConfigPair: name == "encryption_enabled"]*
             )
         )
         ]*

ConfigBlock : blocktype == "resource" and labels[0] is "aws_mq_broker" and pairs contains [
  ConfigPair : name == "publicly_accessible" and value is [
    ConfigConcrete : value matches "TRUE|(T|t)rue"
  ]*
]*

ConfigBlock : blocktype == "resource" and labels[0] is "aws_neptune_cluster_instance" and pairs contains [
  ConfigPair : name == "publicly_accessible" and value is [
    ConfigConcrete : value matches "TRUE|(T|t)rue"
  ]*
]*

ConfigBlock : blocktype == "resource" and labels[0] is "aws_apigatewayv2_route" and (
  pairs contains [
    ConfigPair : name == "authorization_type" and value is [
      ConfigConcrete : value matches "(?i)NONE"
    ]*
  ]* or not pairs contains [
    ConfigPair : name == "authorization_type"
  ]
)

ConfigBlock : blocktype == "resource" and labels[0] is "aws_api_gateway_method" and pairs contains [
  ConfigPair : name == "authorization" and value is [
    ConfigConcrete : value matches "(?i)NONE"
  ]*
]*

ConfigBlock : blocktype == "resource" and labels[0] is "aws_redshift_cluster" and not pairs contains [
  ConfigPair : name == "publicly_accessible" and value is [
    ConfigConcrete : value matches "FALSE|(F|f)alse"
  ]
]*

ConfigBlock : blocktype == "resource" and labels[0] is "aws_db_proxy" and not pairs contains [
  ConfigPair : name == "require_tls" and value is [
    ConfigConcrete : value matches "TRUE|(T|t)rue"
  ]*
]*

ConfigBlock : blocktype == "resource" and labels[0] is "aws_elasticache_replication_group" and not pairs contains [
  ConfigPair : name == "transit_encryption_enabled" and value is [
    ConfigConcrete : value matches "TRUE|(T|t)rue"
  ]*
]*

ConfigBlock : blocktype == "resource" and labels[0] is "aws_sns_topic" and not pairs contains [
    ConfigPair : name == "kms_master_key_id"
]

ConfigBlock : blocktype == "resource" and labels[0] is "aws_db_instance" and pairs contains [
  ConfigPair : name == "replicate_source_db"
]* and not pairs contains [
  ConfigPair : name == "kms_key_id"
]

ConfigBlock : blocktype == "resource" and labels[0] is "aws_db_instance" and not pairs contains [
  ConfigPair : name == "storage_encrypted" and value is [
    ConfigConcrete : value matches "TRUE|(T|t)rue"
  ]
] and not pairs contains [
  ConfigPair : name == "replicate_source_db"
]

ConfigBlock : blocktype == "resource" and labels[0] is "aws_ebs_snapshot_import" and not pairs contains [
  ConfigPair : name == "encrypted" and value is [
    ConfigConcrete : value matches "TRUE|(T|t)rue"
  ]
]

ConfigBlock : blocktype == "resource" and labels[0] is "aws_ebs_snapshot_copy" and not pairs contains [
  ConfigPair : name == "encrypted" and value is [
    ConfigConcrete : value matches "TRUE|(T|t)rue"
  ]
]

ConfigBlock : blocktype == "resource" and labels[0] is "aws_ebs_encryption_by_default" and not pairs contains [
  ConfigPair : name == "enabled" and value is [
    ConfigConcrete : value matches "TRUE|(T|t)rue"
  ]
]

ConfigBlock : blocktype == "resource" and labels[0] is "aws_ebs_volume" and not pairs contains [
  ConfigPair : name == "encrypted" and value is [
    ConfigConcrete : value matches "TRUE|(T|t)rue"
  ]
]

Description.Explanation:
By default, a Compute Engine instance is not a Confidential VM. A Confidential VM uses hardware-based cryptography for data-in-use protection and to support remote attestations. Non-exportable dedicated per-VM instance keys keep VM memory encrypted, thereby protecting VM confidentiality and integrity against cloud provider access via the higher-privileged hypervisor.

<b>Example 1:</b> The following example shows a Terraform configuration that disables Confidential VM by setting <code>enable_confidential_compute</code> to <code>false</code>.
<pre>
resource "google_compute_instance" "default" {
  ...
  confidential_instance_config {
    enable_confidential_compute = false
  }
  ...
}
</pre>

Description.Recommendations:
Enable Confidential VM in supported Google Cloud regions and zones.

<b>Example 2:</b> The following example fixes the problem in <code>Example 1</code>. It enables Confidential VM by setting <code>enable_confidential_compute</code> to <code>true</code>.
<pre>
resource "google_compute_instance" "default" {
  ...
  confidential_instance_config {
    enable_confidential_compute = true
  }
  ...
}
</pre>

Descriptions.Explanation:
Azure shared images are automatically encrypted with server-side encryption using a platform-managed key. An Azure shared image that uses platform-managed encryption keys reduces the organization's control of the shared image and its content. 

<b>Example 1:</b> The following example shows a Terraform configuration that defines an Azure shared image that does not use customer-managed keys for encryption.
<pre>
resource "azurerm_shared_image_version" "aztf016-02-01" {
  name = "0.0.1"
  ...
  target_region {
    name = azurerm_resource_group.example.location
    regional_replica_count = 1
  }
}</pre>

By default, the <code>default_action</code> property is set to <code>"Deny"</code> for <code>IoT Hub</code> resources.

<b>Example 1:</b> The following example shows a configuration that defines an <code>azurerm_iothub</code> resource with <code>default_action</code> not set to a secure value such as <code>"Deny"</code>.
<pre>
resource "azurerm_iothub" "example" {
...
    network_rule_set {
        default_action = "Allow"
    }
...
}

</pre>

By default, the <code>default_action</code> property is set to <code>"Deny"</code> for <code>Key Vault</code> resources.

<b>Example 1:</b> The following example shows a configuration that defines an <code>azurerm_key_vault_managed_hardware_security_module</code> resource with <code>default_action</code> not set to a secure value such as <code>"Deny"</code>.
<pre>
resource "azurerm_key_vault_managed_hardware_security_module" "example" {
...
    network_acls {
        default_action = "Allow"
    }
...
}

</pre>

By default, the <code>minimum_tls_version</code> property is set to <code>"1.2"</code> for <code>App Service</code> resources.

<b>Example 1:</b> The following example shows a configuration that defines an <code>azurerm_windows_web_app_slot</code> resource with <code>minimum_tls_version</code> not set to a secure value such as <code>"1.2"</code>.
<pre>
resource "azurerm_windows_web_app_slot" "example" {
...
    site_config {
        minimum_tls_version = "1.0"
    }
...
}

</pre>

By default, the <code>ftps_state</code> property is set to <code>"AllAllowed"</code> for <code>Functions</code> resources.

<b>Example 1:</b> The following example shows a configuration that defines an <code>azurerm_function_app</code> resource with <code>ftps_state</code> set to an insecure value such as <code>"AllAllowed"</code>.
<pre>
resource "azurerm_function_app" "example" {
...
    site_config {
        ftps_state = "AllAllowed"
    }
...
}

</pre>
<b>Example 2:</b> The following example shows a configuration that defines an <code>azurerm_function_app</code> resource with <code>ftps_state</code> unset.
<pre>
resource "azurerm_function_app" "example" {
...
    site_config {
        #  MISSING ftps_state ...
    }
...
}
</pre>

By default, the <code>ftps_state</code> property is set to <code>"Disabled"</code> for <code>Functions</code> resources.

<b>Example 1:</b> The following example shows a configuration that defines an <code>azurerm_linux_function_app</code> resource with <code>ftps_state</code> set to an insecure value such as <code>"AllAllowed"</code>.
<pre>
resource "azurerm_linux_function_app" "example" {
...
    site_config {
        ftps_state = "AllAllowed"
    }
...
}

</pre>

By default, the <code>ftps_state</code> property is set to <code>"Disabled"</code> for <code>Functions</code> resources.

<b>Example 1:</b> The following example shows a configuration that defines an <code>azurerm_linux_function_app_slot</code> resource with <code>ftps_state</code> set to an insecure value such as <code>"AllAllowed"</code>.
<pre>
resource "azurerm_linux_function_app_slot" "example" {
...
    site_config {
        ftps_state = "AllAllowed"
    }
...
}

</pre>

By default, the <code>ftps_state</code> property is set to <code>"Disabled"</code> for <code>Functions</code> resources.

<b>Example 1:</b> The following example shows a configuration that defines an <code>azurerm_windows_function_app</code> resource with <code>ftps_state</code> set to an insecure value such as <code>"AllAllowed"</code>.
<pre>
